const KEY='sports-bet-autonome-v1';
const initial=()=>({balance:10,matches:[],tickets:[],transactions:[]});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||initial()}catch{state=initial()}for(const t of state.tickets){t.status=({'GAGNÉ':'WON','PERDU':'LOST','EN ATTENTE':'PENDING'})[t.status]||t.status;t.id=t.id.replace(/^SEB-/, 'BET-')}state.transactions=state.transactions||[];let selected={},timer;
const $=id=>document.getElementById(id),money=n=>n.toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})+' €',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function recordActivity(type,amount,details){state.transactions.push({id:'ACT-'+Date.now().toString(36)+'-'+state.transactions.length,date:new Date().toLocaleString('en-GB'),type,amount,balance:state.balance,details})}
function renderAccount(){$('accountBalance').textContent=money(state.balance);$('accountActivity').innerHTML=state.transactions.length?[...state.transactions].reverse().map(t=>`<div class="activityRow"><div><b>${esc(t.details)}</b><small>${esc(t.date)}</small><em>${t.type}</em></div><strong>${t.amount>0?'+':''}${money(t.amount)}<small>Balance ${money(t.balance)}</small></strong></div>`).join(''):'<p class="small">No activity recorded yet.</p>'}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('stateStatus').textContent='Version autonome · données enregistrées dans ce navigateur · aucun mail automatique';return true}catch{$('stateStatus').textContent='Sauvegarde impossible : exporte tes données avant de fermer.';return false}}

function tell(s){$('message').textContent=s;clearTimeout(timer);timer=setTimeout(()=>$('message').textContent='',5000)}
function picks(){return state.matches.filter(m=>selected[m.id]&&!closed(m)).map(m=>{const o=options(m).find(o=>o.key===selected[m.id]);return o?{id:m.id,home:m.home,away:m.away,pick:o.key,label:o.label,short:o.short,matchNumber:m.matchNumber,odd:o.odd,deadline:m.deadline,market:m.market,sport:m.sport,competition:m.competition,resultPath:m.resultPath}:null}).filter(Boolean)}
function combined(list){return list.reduce((a,p)=>a*p.odd,1)}
function chosen(p){return p.label||(p.pick==='1'?p.home:p.pick==='2'?p.away:'Draw')}
const englishSport=s=>({'Volley-ball':'Volleyball','Tennis de Table':'Table tennis','Boxe':'Boxing','Cyclisme':'Cycling','Foot américain':'American football','Hockey s/g':'Ice hockey'}[s]||s);
const englishMarket=s=>({'1/N/2':'Match result','Face à Face':'Head to head','Vainqueur':'Winner','Vainqueur de la compétition':'Competition winner','Plus/Moins':'Over/Under'}[s]||s);
function options(m){return m.outcomes||Object.entries(m.odds||{}).map(([key,odd])=>({key,odd,label:key==='1'?m.home:key==='2'?m.away:'Draw',short:key==='N'?'X':key}))}
function closed(m){return !!m.result||!!(m.deadline&&Date.parse(m.deadline)<=Date.now())}
function visible(includeClosed=false){const q=$('search').value.trim().toLowerCase(),sport=$('sportFilter').value,comp=$('competitionFilter').value;return state.matches.filter(m=>(includeClosed||!closed(m))&&(!sport||m.sport===sport)&&(!comp||m.competition===comp)&&(!q||[m.home,m.away,m.competition,m.region].join(' ').toLowerCase().includes(q)))}
function render(){
 renderAccount();$('latestTicketActions').hidden=!state.tickets.length;$('balance').textContent=money(state.balance);$('stake').max=state.balance;
 for(const m of state.matches)if(closed(m))delete selected[m.id];
 $('matches').innerHTML=visible().map(m=>`<article class="match"><div><div class="matchMeta">${esc(englishSport(m.sport))} · ${esc(m.competition||'Custom match')}<br>${m.startDate?esc(new Date(m.startDate).toLocaleString('en-GB',{timeZone:'Europe/Paris',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}))+' · Paris time':''} ${closed(m)?'· Closed':''}</div><div class="teams">${esc(m.home)}${m.away?'<br><small>vs</small> '+esc(m.away):''}</div><p class="small">${esc(englishMarket(m.market||'Match winner'))}</p></div><div class="choices">${options(m).map(o=>`<button class="choice" data-match="${esc(m.id)}" data-pick="${esc(o.key)}" aria-label="${esc(o.label)} odds ${o.odd}" aria-pressed="${selected[m.id]===o.key}" ${closed(m)?'disabled':''}>${esc(o.short||o.label)}<span>${o.odd.toFixed(2)}</span></button>`).join('')}</div></article>`).join('')||'<p class="catalogEmpty">No matches found. Try another search or refresh the fixtures.</p>';
 const list=picks(),odd=combined(list),stake=Number($('stake').value);
 $('selection').innerHTML=list.length?list.map(p=>`<div class="pick"><b>${esc(p.home)}${p.away?' — '+esc(p.away):''}</b><span> ${esc(chosen(p))} · ${p.odd.toFixed(2)}</span></div>`).join(''):'<p class="empty">Your ticket starts here.<br>Choose 1, X or 2 to make a pick.</p>';
 $('totalOdds').textContent=list.length?odd.toFixed(2):'—';$('potential').textContent=money(list.length&&Number.isFinite(stake)?Math.round(stake*odd*100)/100:0);$('validate').disabled=!list.length||!(stake>=.1&&stake<=state.balance);
 $('results').innerHTML=visible(true).map(m=>`<div class="resultRow"><span>${esc(m.home)}${m.away?' — '+esc(m.away):''}</span><select data-result="${esc(m.id)}" aria-label="Result ${esc(m.home)}" ${m.result?'disabled':''}><option value="">Pending</option>${[...options(m).map(o=>[o.key,o.label]),['void','Void · odds 1']].map(([k,n])=>`<option value="${esc(k)}" ${m.result===k?'selected':''}>${esc(n)}</option>`).join('')}</select></div>`).join('');
 $('ticketCount').textContent=state.tickets.length+' ticket'+(state.tickets.length>1?'s':'');
 $('history').innerHTML=state.tickets.length?[...state.tickets].reverse().map(t=>`<article class="historyCard"><div><span class="badge ${t.status==='WON'?'won':t.status==='LOST'?'lost':''}">${t.status}</span><p><b>${esc(t.id)}</b> · ${esc(t.date)}</p><p>${t.picks.map(p=>`${esc(p.home)}${p.away?' / '+esc(p.away):''} : <b>${esc(chosen(p))}</b>`).join('<br>')}</p></div><div class="historyActions"><p>Stake ${money(t.stake)}</p><p>Odds ${t.odd.toFixed(2)}</p><p><b>${t.status==='WON'?'Virtual return':t.status==='LOST'?'Return':'Potential'} ${money(t.status==='LOST'?0:t.payout)}</b></p><button class="outline" data-print="${t.id}">Digital ticket</button><button class="outline" data-download="${t.id}">Save PDF</button></div></article>`).join(''):'<p class="empty">No tickets yet. Make your first picks above.</p>';
}
function settle(){for(const t of state.tickets){if(t.status!=='PENDING')continue;let won=true,done=true,odd=1;for(const p of t.picks){const r=state.matches.find(m=>m.id===p.id)?.result;if(!r){done=false;continue}if(r!=='void'&&r!==p.pick)won=false;odd*=r==='void'?1:p.odd}if(!won){t.status='LOST';t.payout=0}else if(done){t.status='WON';t.odd=odd;t.payout=Math.round(t.stake*odd*100)/100;state.balance=Math.round((state.balance+t.payout)*100)/100;recordActivity('CREDITED · VALIDATED',t.payout,'Virtual return '+t.id)}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-match]');if(b){const id=b.dataset.match,k=b.dataset.pick;if(selected[id]===k)delete selected[id];else selected[id]=k;render()}const p=e.target.closest('[data-print]');if(p)showTicket(state.tickets.find(t=>t.id===p.dataset.print));const d=e.target.closest('[data-download]');if(d)showTicket(state.tickets.find(t=>t.id===d.dataset.download))});
$('stake').addEventListener('input',render);$('clear').onclick=()=>{selected={};render()};$('adminToggle').onclick=()=>{const open=$('admin').hidden;$('admin').hidden=!open;$('adminToggle').setAttribute('aria-expanded',String(open))};
$('validate').onclick=()=>{const list=picks(),stake=Number($('stake').value);if(!list.length||!Number.isFinite(stake)||stake<.1||stake>state.balance)return tell('Check your stake and balance.');const rounded=Math.round(stake*100)/100;if(rounded>state.balance)return;const odd=combined(list);if(!Number.isFinite(odd*rounded))return tell('The combined odds are too high.');state.balance=Math.round((state.balance-rounded)*100)/100;const t={id:'BET-'+Date.now().toString(36).toUpperCase(),date:new Date().toLocaleString('en-GB'),stake:rounded,picks:list,odd,payout:Math.round(rounded*odd*100)/100,status:'PENDING'};state.tickets.push(t);recordActivity('DEBITED · VALIDATED',-rounded,'Ticket '+t.id);selected={};save();render();tell('Ticket confirmed!');showTicket(t);};
$('matchForm').onsubmit=e=>{e.preventDefault();const home=$('home').value.trim(),away=$('away').value.trim(),odds={'1':Number($('odd1').value),N:Number($('oddN').value),'2':Number($('odd2').value)};if(!home||!away||Object.values(odds).some(n=>!Number.isFinite(n)||n<1.01))return tell('Enter both teams and all three odds.');state.matches.push({id:'m'+Date.now(),home,away,sport:$('sport').value,odds,result:'',demo:false});$('home').value='';$('away').value='';save();filterOptions();render();tell('Match added.');};
$('results').onchange=e=>{const id=e.target.dataset.result,r=e.target.value;if(!id||!r)return;if(!confirm('Confirm this result? Tickets will be settled permanently.')){render();return}state.matches.find(m=>m.id===id).result=r;delete selected[id];settle();save();render();tell('Result recorded. Tickets updated.');};
$('addCredit').onclick=()=>{const n=Number($('credit').value);if(!Number.isFinite(n)||n<.1||n>10000)return tell('Enter between 0.10 and 10,000 virtual euros.');state.balance=Math.round((state.balance+n)*100)/100;recordActivity('CREDITED · VALIDATED',Math.round(n*100)/100,'Virtual credit added');save();render();tell('Virtual credit added.');};$('reset').onclick=()=>{if(confirm('Clear all tickets and restart with 10 virtual euros?')){state.balance=10;state.tickets=[];state.transactions=[];recordActivity('VALIDATED',0,'New simulation session');state.matches=state.matches.map(m=>({...m,result:''}));selected={};save();render()}};
let ticketPdfUrl=null,activeTicket=null,ticketImageUrl=null,ticketImageBlob=null;
function ticketHtml(t){return `<h2>SPORTS BET</h2><p class="center"><b>SIMULATION TICKET<br>NO REAL BET PLACED</b></p><div class="line"></div><p>${esc(t.date)}<br>${esc(t.id)}<br>TYPE: ACCUMULATOR</p><div class="line"></div>${t.picks.map((p,i)=>`<p>${i+1}. ${esc(p.home)}${p.away?' - '+esc(p.away):''}<br> ${esc(chosen(p))}<br>ODDS: ${p.odd.toFixed(2)}</p>`).join('')}<div class="line"></div><p>VIRTUAL STAKE: ${money(t.stake)}<br>COMBINED ODDS: ${t.odd.toFixed(2)}<br>GAIN THEORIQUE: ${money(t.payout)}<br>STATUS: ${t.status==='PENDING'?'JEU EN COURS':t.status}</p><div class="barcode"></div><p class="center">All selections must win.</p>`}
async function showTicket(t){if(!t)return;activeTicket=t;if(ticketPdfUrl)URL.revokeObjectURL(ticketPdfUrl);ticketPdfUrl=URL.createObjectURL(new Blob([await makeTicketPdf(t)],{type:'application/pdf'}));$('downloadPdf').href=ticketPdfUrl;$('downloadPdf').download='SPORTS_BET_'+t.id+'.pdf';$('openPdf').href=ticketPdfUrl;$('ticketPreview').innerHTML=ticketHtml(t);if(!$('ticketDialog').open)$('ticketDialog').showModal();$('shareTicket').disabled=true;$('saveImage').hidden=true;ticketImageBlob=null;try{const blob=await ticketPng(t);if(activeTicket!==t)return;if(ticketImageUrl)URL.revokeObjectURL(ticketImageUrl);ticketImageBlob=blob;ticketImageUrl=URL.createObjectURL(blob);$('saveImage').href=ticketImageUrl;$('saveImage').download='SPORTS_BET_'+t.id+'.png';$('saveImage').hidden=false;$('shareTicket').disabled=false;$('ticketPreview').innerHTML='<img class="receiptImage" src="'+ticketImageUrl+'" alt="SPORTS BET fictional digital ticket">'}catch{tell('Image unavailable. You can still save or open the PDF.')}}
function printTicket(t){if(!t)return;const popup=window.open('','_blank');if(popup){popup.document.open();popup.document.write('<!doctype html><html lang="en"><head><title>SPORTS BET ticket</title><style>@page{size:80mm auto;margin:4mm}body{font:12px Courier,monospace;width:72mm;margin:4mm auto;color:#000}h2,.center{text-align:center}p{line-height:1.5;overflow-wrap:anywhere}.line{border-top:1px dashed #000;margin:12px 0}.barcode{height:28px;background:repeating-linear-gradient(90deg,#000 0px,#000 2px,#fff 2px,#fff 4px);print-color-adjust:exact}button{padding:12px;font:inherit;cursor:pointer}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save as PDF</button>'+(ticketImageUrl&&activeTicket===t?'<img style="width:100%" src="'+ticketImageUrl+'" alt="Fictional ticket">':ticketHtml(t))+'</body></html>');popup.document.close();popup.focus();popup.onload=()=>popup.print();}else{showTicket(t);tell('Use Open PDF, then print from your PDF viewer.')}}
const ticketFonts=[["TicketMono", ""], ["TicketBold", ""], ["TicketLogo", ""]];
let ticketFontsReady;
async function ticketCanvas(t){
 if(!ticketFontsReady)ticketFontsReady=Promise.all(ticketFonts.map(async([name,data])=>{const f=new FontFace(name,'url(data:font/woff;base64,'+data+')');document.fonts.add(await f.load())}));await ticketFontsReady;
 const l=ticketLayout(t);if(l.height>20000)throw Error('Use PDF for long tickets');const canvas=document.createElement('canvas');canvas.width=l.width*2;canvas.height=l.height*2;const ctx=canvas.getContext('2d');if(!ctx)throw Error('No canvas');ctx.scale(2,2);ctx.fillStyle='#fff';ctx.fillRect(0,0,l.width,l.height);ctx.fillStyle='#000';ctx.strokeStyle='#000';
 for(const o of l.ops){if(o.kind==='text'){ctx.font=o.size+'px '+(o.font==='logo'?'TicketLogo':o.font==='bold'?'TicketBold':o.font==='symbol'?'"Segoe UI Emoji", sans-serif':'TicketMono');ctx.textAlign=o.align;ctx.fillText(o.text,o.x,o.y)}else if(o.kind==='line'){ctx.beginPath();ctx.setLineDash([6,5]);ctx.moveTo(o.x,o.y);ctx.lineTo(o.x2,o.y);ctx.stroke();ctx.setLineDash([])}else if(o.kind==='rect'){ctx.lineWidth=2;ctx.strokeRect(o.x,o.y,o.w,o.h);ctx.lineWidth=1}else if(o.kind==='bar')ctx.fillRect(o.x,o.y,o.w,o.h)}
 const pixels=ctx.getImageData(0,0,canvas.width,canvas.height);for(let i=0;i<pixels.data.length;i+=4){const g=Math.round(.299*pixels.data[i]+.587*pixels.data[i+1]+.114*pixels.data[i+2]);pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=g}ctx.putImageData(pixels,0,0);return canvas;
}
async function ticketPng(t){const canvas=await ticketCanvas(t);return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('No image')),'image/png'))}

$('shareTicket').onclick=async()=>{if(!ticketImageBlob||!activeTicket)return;const file=new File([ticketImageBlob],'SPORTS_BET_'+activeTicket.id+'.png',{type:'image/png'});if(navigator.canShare?.({files:[file]})&&navigator.share){try{await navigator.share({files:[file],title:'SPORTS BET digital ticket'});return}catch(e){if(e.name==='AbortError')return}}$('saveImage').click();tell('Save the ticket image, then attach it to your message.');};
$('accountButton').onclick=()=>{renderAccount();$('accountDialog').showModal()};$('closeAccount').onclick=()=>$('accountDialog').close();$('accountCreditForm').onsubmit=e=>{e.preventDefault();const n=Number($('accountAmount').value);if(!Number.isFinite(n)||n<.1||n>10000)return tell('Enter between 0.10 and 10,000 virtual euros.');const amount=Math.round(n*100)/100;state.balance=Math.round((state.balance+amount)*100)/100;recordActivity('CREDITED · VALIDATED',amount,'Virtual credit added');save();render();tell('Virtual credit added.');};
$('latestTicket').onclick=()=>showTicket(state.tickets.at(-1));$('closeTicket').onclick=()=>$('ticketDialog').close();$('dialogPrint').onclick=()=>printTicket(activeTicket);
function filterOptions(){const sports=[...new Set(state.matches.map(m=>m.sport))].sort(),comps=[...new Set(state.matches.filter(m=>!$('sportFilter').value||m.sport===$('sportFilter').value).map(m=>m.competition).filter(Boolean))].sort();const sv=$('sportFilter').value,cv=$('competitionFilter').value;$('sportFilter').innerHTML='<option value="">All sports</option>'+sports.map(s=>`<option ${s===sv?'selected':''} value="${esc(s)}">${esc(englishSport(s))}</option>`).join('');$('competitionFilter').innerHTML='<option value="">All competitions</option>'+comps.map(c=>`<option ${c===cv?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}
function merge(matches){for(const t of state.tickets)for(const p of t.picks){const m=matches.find(m=>m.id===p.id)||state.matches.find(m=>m.id===p.id);if(m){p.sport=p.sport||m.sport;p.competition=p.competition||m.competition;p.resultPath=p.resultPath||m.resultPath;p.deadline=p.deadline||m.deadline}}const old=new Map(state.matches.map(m=>[m.id,m]));const preserve=state.matches.filter(m=>!m.demo&&(!m.official||state.tickets.some(t=>t.picks.some(p=>p.id===m.id))));const all=new Map(preserve.map(m=>[m.id,m]));for(const m of matches)all.set(m.id,{...m,result:old.get(m.id)?.result||''});state.matches=[...all.values()].sort((a,b)=>(a.startDate||'z').localeCompare(b.startDate||'z'));save();filterOptions();render()}
function loadCatalog(){filterOptions();render();$('catalogStatus').textContent=state.matches.filter(m=>!closed(m)).length+' matchs disponibles · ajout et résultats manuels';}
$('search').oninput=render;$('sportFilter').onchange=()=>{$('competitionFilter').value='';filterOptions();render()};$('competitionFilter').onchange=render;$('refresh').onclick=loadCatalog;
$('backup').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='SPORTS_BET_sauvegarde.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error();const d=JSON.parse(await file.text());if(!d||!Number.isFinite(d.balance)||d.balance<0||!Array.isArray(d.matches)||!Array.isArray(d.tickets)||!Array.isArray(d.transactions)||d.matches.some(m=>typeof m.id!=='string'||typeof m.home!=='string'||typeof m.sport!=='string'||!Array.isArray(m.outcomes)&&!m.odds)||d.tickets.some(t=>typeof t.id!=='string'||!Array.isArray(t.picks)||!Number.isFinite(t.stake)||!Number.isFinite(t.odd)||!Number.isFinite(t.payout)||!['PENDING','WON','LOST'].includes(t.status)))throw Error();if(confirm('Remplacer les données de ce navigateur par cette sauvegarde ?')){state=d;selected={};save();loadCatalog();tell('Sauvegarde restaurée.')}}catch{tell('Fichier de sauvegarde invalide.')}finally{e.target.value=''}};
loadCatalog();save();window.addEventListener('pageshow',loadCatalog);
